func NormalizeSearchPath(p string) string {
	p = strings.Trim(strings.ToLower(strings.TrimSpace(p)), "/")
	return strings.ReplaceAll(p, "_", "-")
}

func LookupSearchCollection(path string) (*SearchCollectionDef, bool) {
	norm := NormalizeSearchPath(path)
	for _, c := range AllSearchCollections {
		if NormalizeSearchPath(c.CanonicalPath) == norm {
			return c, true
		}
		for _, a := range c.Aliases {
			if NormalizeSearchPath(a) == norm {
				return c, true
			}
		}
	}
	return nil, false
}
